import{z as E,x as p,o as t,c as A,q as B,j as r,D as o,d as e,s,S as i,b as l}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"标签平滑","description":"","frontmatter":{"title":"标签平滑","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/label-smoothing-lm.md","filePath":"llm/label-smoothing-lm.md","lastUpdated":1791063341000}'),d={name:"llm/label-smoothing-lm.md"};function m(h,a,u,g,P,f){const n=p("Mermaid");return t(),A("div",null,[a[2]||(a[2]=B('<h1 id="标签平滑" tabindex="-1">标签平滑 <a class="header-anchor" href="#标签平滑" aria-label="Permalink to &quot;标签平滑&quot;">​</a></h1><div class="epigraph"><p>把 one-hot 目标改成正确类 $1-\\varepsilon$、其余均分 $\\varepsilon$，交叉熵不再奖励无限大的 logit 间隔，校准往往变好，最大似然则变差。</p><footer>—— Szegedy et al., Rethinking the Inception Architecture, CVPR 2016；分析见 Müller, Kornblith &amp; Hinton, NeurIPS 2019</footer></div><p><a href="/llm/attention-dropout-droppath">上一课</a>把激活与路由上的噪声写完。缺口转到<strong>目标</strong>侧：Vaswani 等人在翻译上用了 \\(\\varepsilon=0.1\\) 的标签平滑（label smoothing）。语言模型若仍把目标当 one-hot，CE 会推动正确类 logit 相对其余趋向 \\(+\\infty\\)，这与 <a href="/llm/output-init-logit-scale">输出初始化</a> 钉住的有限尺度、以及主干 <a href="/llm/z-loss">z-loss</a> 要压的 LSE，方向相反。本课写平滑如何改损失，以及因果 LM 为什么常常不用它。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标准下一 token 损失是 \\(-\\log p_{y}\\)。最优是 \\(p_y=1\\)，需要 \\(\\ell_y-\\ell_j\\to\\infty\\)。训练中这意味着输出层与最后一层范数可以无界增长，半精度与校准先坏。Szegedy 等人把目标改成</p> \\[q_y=1-\\varepsilon,\\qquad q_j=\\frac{\\varepsilon}{|V|-1}\\ (j\\neq y), \\]<p>最小化 \\(\\mathrm{KL}(q\\|p)\\)（等价于对 \\(q\\) 的交叉熵）。正确类不再要求概率 1，错误类也分到一点质量，logit 间隔有限。Müller 等人指出：平滑抑制的是正确类相对最强错误类的过度自信，表示空间里同类更紧、类间更分离，对蒸馏当教师更友好。</p><p>因果 LM 的词表是 \\(10^4\\)–\\(10^5\\) 量级，\\(\\varepsilon/(|V|-1)\\) 极小。同样 \\(\\varepsilon=0.1\\)，分到每个错误 token 的目标质量可以忽略，平滑几乎只在「正确类不要 1」上起作用。翻译词表较小、且评测是 BLEU 不是 PPL，原论文的 0.1 不能直接贴到 GPT。</p><p><span class="marginnote">平滑改的是训练目标，不是解码温度。用平滑训完再以温度 1 解码，模型会偏「平」；若把温度降下来追 PPL，等于部分撤销平滑。报 PPL 的预训练不要默默开平滑。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现上不必物化 \\(q\\)：</p> \\[\\mathcal{L}=-(1-\\varepsilon)\\log p_y-\\varepsilon\\,\\mathrm{mean}_{j\\neq y}\\log p_j, \\]<p>第二项等于 \\(\\varepsilon\\) 乘（全体 token 的平均 \\(\\log p\\) 再扣掉正确类一项的修正）。与全词表 softmax 的融合核要一起改，Cut CE 一类只取正确类与分母的实现，必须补上对 \\(\\log p_j\\) 的均值，否则平滑是错的。</p><p>\\(\\varepsilon\\) 的扫：翻译 / 分类 0.1 是文献常客；LM 若用，数量级更小（0.01 或更低），并<strong>同时看</strong> CE 与下游，不要只看训练 CE——训练 CE 几乎必升。与 dropout 同时开时，噪声来源变两个，消融应能单独关平滑。</p><p>不要把平滑当成 class-balanced 的稀有词保护：它对所有错误类一视同仁，稀有词与高频词分到同样的 \\(\\varepsilon/(|V|-1)\\)。要照顾频次，应改采样或损失权重，不是加大 \\(\\varepsilon\\)。</p><p><span class="marginnote">数字实例：词表 \\(|V|=32768\\)、\\(\\varepsilon=0.1\\) 时，每个错误 token 分到的目标是 \\(0.1/32767\\approx 3\\times 10^{-6}\\)——一百万分之三。这就是为什么大词表 LM 上平滑「感觉不到」：软目标几乎全部体现在「正确类降到 0.9」这一处，而不是真的在教模型认识错误类。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>对 logits 的梯度从 \\(p-y\\) 变成 \\(p-q\\)。正确类目标变小，梯度不再拼命抬 \\(\\ell_y\\)；错误类目标非零，梯度轻微抬所有错误 logit——更准确地说，相对 softmax 均值做微小拉动。结果是 LSE 增长变慢，与 z-loss 同向但弱得多，不能替代 z-loss：平滑不显式惩罚 \\(z^2\\)，只改目标。</p><p>Müller 等人还观察到：平滑使教师的 \\(p\\) 更适合当蒸馏目标，因为不再接近 one-hot。若你的流水线没有蒸馏，这个优点不存在。对指令微调，平滑可能伤害「必须选确定答案」的题；对开放生成，可能减轻个别 token 的过度自信。要按任务消融，不要作为稳定训练的默认保险。</p><p><span class="marginnote">直觉类比：把训练想成老师批卷。one-hot 目标下，老师只在乎你把正确答案的分数推向无穷高，哪怕其他题全空白也行；平滑目标下，老师同时要求「别把其他选项打成 0 分、也别把正确项吹成满分」。后者逼出的模型输出更「谦虚」，这就是校准变好的来源。</span></p>',20)),(t(),r(i,null,{default:o(()=>[s(n,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20OH%5B%22one-hot%20%E7%9B%AE%E6%A0%87%E4%B8%8B%E7%9A%84%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20%20%20A1%5B%22%E6%A2%AF%E5%BA%A6%20p%20-%20y%22%5D%20--%3E%20B1%5B%22%E5%8F%AA%E6%8E%A8%E9%AB%98%E6%AD%A3%E7%A1%AE%E7%B1%BB%20logit%22%5D%0A%20%20%20%20B1%20--%3E%20C1%5B%22%E9%97%B4%E9%9A%94%E8%B6%8B%E4%BA%8E%E6%97%A0%E7%A9%B7%22%5D%0A%20%20end%0A%20%20subgraph%20SM%5B%22%E5%B9%B3%E6%BB%91%E7%9B%AE%E6%A0%87%E4%B8%8B%E7%9A%84%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20%20%20A2%5B%22%E6%A2%AF%E5%BA%A6%20p%20-%20q%22%5D%20--%3E%20B2%5B%22%E6%AD%A3%E7%A1%AE%E7%B1%BB%E5%B0%91%E6%8E%A8%E4%B8%80%E7%82%B9%22%5D%0A%20%20%20%20A2%20--%3E%20C2%5B%22%E9%94%99%E8%AF%AF%E7%B1%BB%E8%BD%BB%E5%BE%AE%E6%89%98%E5%BA%95%22%5D%0A%20%20%20%20B2%20--%3E%20D2%5B%22LSE%20%E5%A2%9E%E9%95%BF%E5%8F%98%E6%85%A2%22%5D%0A%20%20%20%20C2%20--%3E%20D2%0A%20%20end%0A%20%20C1%20-.%20%22%E6%96%B9%E5%90%91%E7%9B%B8%E5%8F%8D%22%20.-%3E%20D2%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"边界",tabindex:"-1"},[e("边界 "),l("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[4]||(a[4]=l("p",null,[e("标签平滑与 label noise（随机关错标签）不是同一件事：前者是确定的软目标，后者是随机错误。也不要和 Mixup / token dropout 混写。评测 PPL、BPB 必须在"),l("strong",null,"未平滑"),e("的 CE 上算，否则与历史检查点不可比。下一课的困惑度定义以硬目标 CE 为准；若训练用了平滑，日志里应同时打 "),l("code",null,"ce_hard"),e(" 与 "),l("code",null,"ce_smooth"),e("。")],-1)),a[5]||(a[5]=l("p",null,[l("span",{class:"marginnote"},"常见误区：初学者容易以为「开了平滑，PPL 就该变好」。实际上平滑的交叉熵是换了一个更容易的目标，数值天然更低，但这个数不能和历史检查点比较。困惑度必须用同一把尺子——硬目标 CE——去量，否则曲线下降只是换了考卷，不是学生变聪明。")],-1)),(t(),r(i,null,{default:o(()=>[s(n,{id:"mermaid-64",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E6%AD%A3%E7%A1%AE%E7%B1%BB%20y%22%5D%20--%3E%20Q%5B%22%E8%BD%AF%E7%9B%AE%E6%A0%87%20q%22%5D%0A%20%20EPS%5B%22epsilon%22%5D%20--%3E%20Q%0A%20%20Q%20--%3E%20KL%5B%22CE(q%2C%20p)%22%5D%0A%20%20P%5B%22%E6%A8%A1%E5%9E%8B%20p%22%5D%20--%3E%20KL%0A%20%20KL%20--%3E%20GAP%5B%22%E6%9C%89%E9%99%90%20logit%20%E9%97%B4%E9%9A%94%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l("h2",{id:"小结",tabindex:"-1"},[e("小结 "),l("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[7]||(a[7]=l("ul",null,[l("li",null,"标签平滑把 one-hot 改成 \\(1-\\varepsilon\\) 与均分 \\(\\varepsilon\\)，阻止 CE 要求无限间隔。"),l("li",null,"大词表 LM 上每错误类分到的质量极小；翻译上的 0.1 不是 LM 默认。"),l("li",null,"训练 CE 会升；报 PPL 必须另打硬目标 CE。"),l("li",null,"它弱于 z-loss，也不是稀有词加权；与 dropout 分开消融。"),l("li",null,"出处：Szegedy et al., CVPR 2016；Müller, Kornblith & Hinton, NeurIPS 2019；Vaswani et al. 在翻译中的使用。")],-1))])}const b=E(d,[["render",m]]);export{c as __pageData,b as default};
